ALTER TABLE storage_providers ADD COLUMN purpose text NOT NULL DEFAULT 'payload' CHECK(purpose IN ('payload','artifacts','backups'));
CREATE UNIQUE INDEX one_artifact_provider ON storage_providers(purpose) WHERE purpose='artifacts' AND enabled;
CREATE TABLE artifacts(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),provider_id uuid NOT NULL REFERENCES storage_providers(id),key_id uuid NOT NULL REFERENCES key_versions(id),salt bytea NOT NULL,filename text NOT NULL,content_type text NOT NULL,state text NOT NULL DEFAULT 'writing' CHECK(state IN ('writing','ready','deleting','deleted')),size bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '1 day');
CREATE INDEX artifacts_owner ON artifacts(owner_id,created_at);
CREATE INDEX artifacts_provider ON artifacts(provider_id);
CREATE INDEX artifacts_key ON artifacts(key_id);
CREATE TABLE artifact_chunks(artifact_id uuid NOT NULL REFERENCES artifacts(id),offset_bytes bigint NOT NULL,length_bytes int NOT NULL,object_key text NOT NULL UNIQUE,PRIMARY KEY(artifact_id,offset_bytes));
CREATE TABLE artifact_credentials(id uuid PRIMARY KEY,artifact_id uuid NOT NULL REFERENCES artifacts(id),user_session_id uuid REFERENCES web_sessions(id),token_hash text NOT NULL UNIQUE,state text NOT NULL DEFAULT 'new' CHECK(state IN ('new','leased','completed')),session_hash text UNIQUE,fence bigint NOT NULL DEFAULT 0,writer_until timestamptz,coverage jsonb NOT NULL DEFAULT '[]',expires_at timestamptz NOT NULL);
CREATE INDEX artifact_credentials_artifact ON artifact_credentials(artifact_id);
CREATE INDEX artifact_credentials_session ON artifact_credentials(user_session_id);
CREATE TABLE reports(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),transfer_id uuid NOT NULL REFERENCES transfers(id),kind text NOT NULL CHECK(kind IN ('user','admin')),revision int NOT NULL,canonical_hash text NOT NULL,key_id uuid NOT NULL REFERENCES key_versions(id),snapshot_envelope bytea,state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','trashed','purged')),locale text NOT NULL,timezone text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(transfer_id,kind,revision));
CREATE INDEX reports_owner ON reports(owner_id,created_at);
CREATE INDEX reports_key ON reports(key_id);
CREATE FUNCTION protect_report_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF ROW(NEW.id,NEW.owner_id,NEW.transfer_id,NEW.kind,NEW.revision,NEW.canonical_hash,NEW.locale,NEW.timezone,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.owner_id,OLD.transfer_id,OLD.kind,OLD.revision,OLD.canonical_hash,OLD.locale,OLD.timezone,OLD.created_at) THEN RAISE EXCEPTION 'report revision is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.state='purged' AND NEW.state<>'purged' THEN RAISE EXCEPTION 'purged report cannot be restored' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER reports_immutable BEFORE UPDATE ON reports FOR EACH ROW EXECUTE FUNCTION protect_report_revision();
CREATE TABLE report_artifacts(report_id uuid NOT NULL REFERENCES reports(id),artifact_id uuid NOT NULL REFERENCES artifacts(id),format text NOT NULL CHECK(format IN ('json','csv','pdf')),PRIMARY KEY(report_id,format));
CREATE INDEX report_artifacts_artifact ON report_artifacts(artifact_id);
CREATE TABLE report_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,report_id uuid NOT NULL REFERENCES reports(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX report_history_report ON report_history(report_id,id);
CREATE TABLE export_jobs(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('user','admin')),format text NOT NULL CHECK(format IN ('json','csv')),compression text NOT NULL CHECK(compression IN ('auto','none','gzip','zip')),state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','snapshotting','materialized','rendering','completed','failed','cancelled')),fence bigint NOT NULL DEFAULT 0,lease_until timestamptz,snapshot_at timestamptz,snapshot_bytes bigint,rows_count int NOT NULL DEFAULT 0,processed int NOT NULL DEFAULT 0,artifact_id uuid REFERENCES artifacts(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),error_code text);
CREATE INDEX export_jobs_owner ON export_jobs(owner_id,created_at);
CREATE INDEX export_jobs_schedule ON export_jobs(state,created_at);
CREATE INDEX export_jobs_artifact ON export_jobs(artifact_id);
CREATE TABLE export_rows(job_id uuid NOT NULL REFERENCES export_jobs(id),ordinal bigint NOT NULL,value jsonb NOT NULL,PRIMARY KEY(job_id,ordinal));
CREATE TABLE saved_views(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,filter jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX saved_views_owner ON saved_views(owner_id,created_at);
CREATE TABLE bulk_jobs(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),action text NOT NULL CHECK(action IN ('revoke','cancel_upload')),state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','completed','cancelled')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX bulk_jobs_owner ON bulk_jobs(owner_id,created_at);
CREATE TABLE bulk_items(job_id uuid NOT NULL REFERENCES bulk_jobs(id),subject_id uuid NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','done','conflict')),PRIMARY KEY(job_id,subject_id));
